# Products on CUDA: generated by cuTile at full precision and in TF32, with an
# epilogue, a conversion to BFloat16, half operands, a product spelled as a
# broadcast and a sum, and a long sum split among blocks; and by cuBLAS in
# either orientation, batched and in half precision, with the work after the
# product a kernel of its own, each product of a kernel of several, and
# products alike but for where their operands start as one call.
include("../fixtures/programs.jl")

@testset "products on cuTile" begin
    w, x, b = Float32.(data(96, 80; scale = 0.1)), Float32.(data(80, 112)), Float32.(data(96))
    for target in (T.CUDATarget(T.cuTileGenerator()), T.CUDATarget(T.cuTileGenerator(); precision = :tf32))
        p = trace((w, x, b) -> gelu.(w * x .+ b), w, x, b)
        ex = prepare(p, CuArray(w), CuArray(x), CuArray(b); target)
        @test any(d -> !(d isa C.FloorKernels) && d.schedule.sketch === :product, ex.kernels)
        @test isapprox(Array(only(C.leaves(outputs(execute!(ex))))), interpret(p, w, x, b); rtol = target.precision === :tf32 ? 1.0e-2 : 1.0e-4)
    end
    # A conversion to BFloat16 is part of the epilogue: one kernel, and
    # only the BFloat16 result is stored.
    p = trace((w, x, b) -> BFloat16.(gelu.(w * x .+ b)), w, x, b)
    ex = prepare(p, CuArray(w), CuArray(x), CuArray(b); target = T.CUDATarget(T.cuTileGenerator(); precision = :tf32))
    @test length(ex.kernels) == 1 && only(ex.kernels).schedule.sketch === :product
    y = only(C.leaves(outputs(execute!(ex))))
    @test eltype(y) === BFloat16
    @test isapprox(Float32.(Array(y)), Float32.(interpret(p, w, x, b)); rtol = 1.0e-2)
    # Half operands accumulate in Float32 and round once.
    h, y = Float16.(data(64, 48; scale = 0.1)), Float16.(data(48, 32))
    p = trace((h, y) -> h * y, h, y)
    ex = prepare(p, CuArray(h), CuArray(y); target = T.CUDATarget(T.cuTileGenerator()))
    @test any(d -> !(d isa C.FloorKernels) && d.schedule.sketch === :product, ex.kernels)
    @test isapprox(Array(only(C.leaves(outputs(execute!(ex))))), interpret(p, h, y); rtol = eps(Float16))
    # A product spelled as a broadcast and a sum is a product too.
    a, c = Float32.(data(64, 48; scale = 0.1)), Float32.(data(48, 80))
    ex = prepare(trace(spelled_product, a, c), CuArray(a), CuArray(c); target = T.CUDATarget(T.cuTileGenerator()))
    @test any(d -> !(d isa C.FloorKernels) && d.schedule.sketch === :product, ex.kernels)
    @test isapprox(Array(only(C.leaves(outputs(execute!(ex))))), a * c; rtol = 1.0e-4)
    # A long sum over a small output splits among blocks (split-K) and merges.
    u, z = Float32.(data(64, 3000; scale = 0.01)), Float32.(data(3000, 48))
    for target in (T.CUDATarget(T.cuTileGenerator()), T.CUDATarget(T.cuTileGenerator(); precision = :tf32))
        p = trace((u, z) -> u * z, u, z)
        ex = prepare(p, CuArray(u), CuArray(z); target)
        @test any(d -> !(d isa C.FloorKernels) && d.schedule.sketch === :product && d.schedule.splits > 1, ex.kernels)
        @test isapprox(Array(only(C.leaves(outputs(execute!(ex))))), interpret(p, u, z); rtol = target.precision === :tf32 ? 1.0e-2 : 1.0e-4)
    end
end

@testset "products on cuBLAS" begin
    @test Base.get_extension(Tempest, :cuBLASExt) !== nothing
    built(ex) = [d for d in ex.kernels if d isa Base.get_extension(Tempest, :cuBLASExt).BuiltProduct]
    a, b = Float32.(data(96, 80; scale = 0.1)), Float32.(data(80, 112))
    at, bt = permutedims(a), permutedims(b)
    A, B = Float32.(data(32, 24, 5; scale = 0.1)), Float32.(data(24, 40, 5; scale = 0.2))
    # Factors in either orientation, a result stored transposed, a batch,
    # and half factors accumulating in Float32.
    layouts = [((a, b) -> a * b, (a, b)), ((at, b) -> transpose(at) * b, (at, b)),
        ((a, bt) -> a * transpose(bt), (a, bt)), ((at, bt) -> transpose(at) * transpose(bt), (at, bt)),
        ((a, b) -> C.contract(a, b, (1, 2), (2, 3), (3, 1)), (a, b)), ((A, B) -> C.contract(A, B, (1, 2, 4), (2, 3, 4), (1, 3, 4)), (A, B)),
        ((a, b) -> a * b, (Float16.(a), Float16.(b))), ((a, b) -> a * b, (BFloat16.(a), BFloat16.(b)))]
    for (f, args) in layouts, target in (T.CUDATarget(T.cuBLASProducts()), T.CUDATarget(T.cuBLASProducts(); precision = :tf32))
        p = trace(f, args...)
        ex = prepare(p, map(CuArray, args)...; target)
        @test length(built(ex)) == 1
        rtol = eltype(args[1]) === Float32 ? (target.precision === :tf32 ? 1.0e-2 : 1.0e-5) : 2 * eps(eltype(args[1]))
        @test isapprox(Float32.(Array(only(C.leaves(outputs(execute!(ex)))))), Float32.(interpret(p, args...)); rtol)
    end
    # With work after the product, cuBLAS's candidate is the product
    # alone, and the work after it a kernel of its own: at a size where
    # the product by cuBLAS is cheaper than the fused reduction.
    left, right = Float32.(data(256, 192; scale = 0.1)), Float32.(data(192, 224))
    w = Float32.(data(256; scale = 0.3))
    p = trace((a, b, w) -> tanh.(a * b .+ w), left, right, w)
    ex = prepare(p, CuArray(left), CuArray(right), CuArray(w); target = T.CUDATarget(T.cuBLASProducts()))
    @test length(built(ex)) == 1 && length(taken(ex)) == 1 && length(ex.kernels) == 2
    @test isapprox(Array(only(C.leaves(outputs(execute!(ex))))), interpret(p, left, right, w); rtol = 1.0e-5)
    ex = prepare(trace((a, b) -> a * b, a, b), CuArray(a), CuArray(b); target = T.CUDATarget(T.cuTileGenerator()))
    @test isempty(built(ex))
    # Products the generator groups as one kernel, the first by a constant
    # zero, which is no product of two factors: the others are cuBLAS's
    # candidates, not only the kernel's first fold, and alike, one call.
    grouped(ex) = [d for d in ex.kernels if d isa Base.get_extension(Tempest, :cuBLASExt).BuiltProducts]
    u, v, y = single(data(512, 512; scale = 0.1)), single(data(512, 512)), single(data(512, 512; scale = 0.3))
    p = trace((u, v, y) -> (u * fill!(similar(v), 0), u * v, u * y), u, v, y)
    ex = prepare(p, CuArray(u), CuArray(v), CuArray(y); target = T.CUDATarget(T.cuBLASProducts()))
    @test isempty(built(ex)) && length(only(grouped(ex)).products) == 2
    @test agree(C.leaves(outputs(execute!(ex))), C.leaves(interpret(p, u, v, y)); rtol = 1.0e-5)
    # Products of parts of one value, which the generator groups as one
    # kernel, alike in all but where their operands start: one call.
    whole = single(data(64, 8 * 128; scale = 0.1))
    states = [single(data(128, 64, 16; scale = 0.01 * k)) for k in 1:8]
    parts(a, s...) = ntuple(k -> C.contract(a[:, (128k - 127):128k], s[k], (1, 4), (4, 2, 3), (1, 2, 3)), 8)
    p = trace(parts, whole, states...)
    ex = prepare(p, CuArray(whole), map(CuArray, states)...; target = T.CUDATarget(T.cuBLASProducts()))
    @test length(ex.kernels) == 1 && length(only(grouped(ex)).products) == 8
    @test agree(C.leaves(outputs(execute!(ex))), C.leaves(interpret(p, whole, states...)); rtol = 1.0e-5)
end

# A product's call is configured on its task's handle, the stream it runs on
# and the workspace it writes set by one call and read by the next, and
# writes its executable's workspace, which nothing else does: two programs'
# products run at once on two streams on state of their own. On one handle
# per context, two programs called at once from two threads failed the first
# round on GB10 and on RTX 6000 Ada, cuBLAS's internal error on that call
# and every later one on the handle; a handle per task alone turned those
# into silently wrong results, 780 of 4000 on GB10, the products running
# beside each other on the one workspace. A graph recorded of a program's
# products leases its executable's workspace and constants, none of
# another's. The calls at once, from threads, are in fixtures/at_once.jl,
# run in a process of its own: the test runner's workers have one thread,
# on which two tasks never call at once and the shared handle passed.
@testset "cuBLAS products of two programs at once" begin
    Ext = Base.get_extension(Tempest, :cuBLASExt)
    took, done = Channel{Any}(2), Base.Event()
    holding = [Threads.@spawn (put!(took, Ext.handle()); wait(done)) for _ in 1:2]
    held = [take!(took) for _ in 1:2]
    notify(done)
    foreach(wait, holding)
    @test held[1] != held[2]
    a, b = Float32.(data(96, 80; scale = 0.1)), Float32.(data(80, 112))
    target = T.CUDATarget(T.cuBLASProducts())
    scratch(ex) = only(unique(l.scratch for l in ex.launches if l isa Ext.Product))
    arrays(s) = (s.workspace, s.one, s.zero)
    for capture in (false, true)
        cs = [compile((a, b) -> a * b, CuArray(a), CuArray(b); target, capture) for _ in 1:2]
        ours, theirs = scratch(cs[1].executable), scratch(cs[2].executable)
        @test isdisjoint(map(pointer, arrays(ours)), map(pointer, arrays(theirs)))
        if capture
            leased = [c.executable.captured.graph.memory for c in cs]
            @test all(x -> x.data[] in leased[1], arrays(ours)) && all(x -> x.data[] in leased[2], arrays(theirs))
            @test isdisjoint(leased[1], leased[2])
        end
    end
    # A decider builds the claims it times on resources of its own, which
    # the executable built after it does not share: a product no
    # preparation here has decided, so that its claims are built and timed.
    c, d = Float32.(data(72, 88; scale = 0.1)), Float32.(data(88, 104))
    s = C.setup(trace((c, d) -> c * d, c, d); target, measure = :all)
    ex = C.prepared(s, C.decide!(s), CuArray(c), CuArray(d))
    deciders = only(r for r in values(s.decider.resources.made) if r isa Ext.Scratch)
    any(l -> l isa Ext.Product, ex.launches) && @test isdisjoint(map(pointer, arrays(deciders)), map(pointer, arrays(scratch(ex))))
    @test at_once("cuBLAS")
end

# An executable's workspace is its own, and goes with it: 64 programs
# prepared and let go hold none of theirs once collected, nor does the
# decider that timed claims for one (a product no preparation here has
# decided). Each is prepared in a function of its own: code at the top
# level keeps what it computed alive until it ends.
@testset "cuBLAS workspaces go with their executables" begin
    Ext = Base.get_extension(Tempest, :cuBLASExt)
    a, b = Float32.(data(96, 80; scale = 0.1)), Float32.(data(80, 112))
    p = trace((a, b) -> a * b, a, b)
    target = T.CUDATarget(T.cuBLASProducts())
    workspace(ex) = only(unique(l.scratch for l in ex.launches if l isa Ext.Product)).workspace
    held = map(_ -> WeakRef(workspace(prepare(p, CuArray(a), CuArray(b); target))), 1:64)
    function decided(c, d)
        s = C.setup(trace((c, d) -> c * d, c, d); target, measure = :all)
        C.decide!(s)
        WeakRef(only(r for r in values(s.decider.resources.made) if r isa Ext.Scratch).workspace)
    end
    push!(held, decided(Float32.(data(56, 72; scale = 0.1)), Float32.(data(72, 40))))
    foreach(_ -> GC.gc(true), 1:3)
    @test count(w -> w.value !== nothing, held) == 0
end
